const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const date = '2017-09-24';
  const endDate = '2017-09-25'; // For a single day, filter exactly.
  const scale = 100; // Sentinel-2 resolution for water can be lower than 10m to avoid speckle but still capture detail. Using 100m for faster aggregation.

  // Define approximate geometries for the western and eastern basins of Lake Erie.
  // These are simplified rectangles.
  const westernBasin = ee.Geometry.Rectangle([-83.5, 41.3, -82.2, 42.1]); // Covers the area west of Pelee Island
  const easternBasin = ee.Geometry.Rectangle([-79.5, 42.3, -78.6, 42.9]); // Covers the area east of Long Point

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterDate(date, endDate)
    .filterBounds(westernBasin.union(easternBasin));

  // Function to mask clouds in Sentinel-2 SR data
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0).and(
      qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000) // Scale to reflectance
      .select(['B2', 'B3', 'B4', 'B5', 'B8', 'B11', 'B12']) // Select relevant bands
      .copyProperties(image, ['system:time_start']);
  }

  // Apply cloud mask and select relevant bands.
  collection = collection.map(maskS2clouds);

  const imageCount = collection.size().getInfo();
  if (imageCount === 0) {
    console.log(`No Sentinel-2 images found for ${date}.`);
    console.log('C1');
    return;
  }

  // Select the least cloudy image for the day, or just take the first one if only one exists.
  // For a specific date, we expect a single pass, so the first image should be sufficient.
  // We can't use 'CLOUDY_PIXEL_PERCENTAGE' after `maskS2clouds` as it removes the property.
  // Let's simply take the first image after filtering for the date.
  const image = ee.Image(collection.first());

  // 3. Processing: Calculate Normalized Difference Chlorophyll Index (NDCI)
  // NDCI = (B5 - B4) / (B5 + B4) - uses Red Edge 1 (B5) and Red (B4)
  // This index is sensitive to chlorophyll content in water bodies.
  const ndci = image.normalizedDifference(['B5', 'B4']).rename('NDCI');

  // Calculate mean NDCI for each basin
  const getBasinStats = async (geometry, basinName) => {
    const stats = ndci.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9,
      crs: 'EPSG:4326' // Specify CRS for consistency
    });

    const meanNDCI = await stats.get('NDCI').getInfo();
    const pixelCount = await stats.get('count').getInfo();

    return {
      name: basinName,
      ndci: meanNDCI,
      pixels: pixelCount
    };
  };

  const westernStats = await getBasinStats(westernBasin, 'Western Basin');
  const easternStats = await getBasinStats(easternBasin, 'Eastern Basin');

  // 4. Validation & Final Answer
  console.log(`Image count: ${imageCount}`);
  console.log(`Western Basin NDCI: ${westernStats.ndci ? westernStats.ndci.toFixed(3) : 'N/A'} (Pixels: ${westernStats.pixels})`);
  console.log(`Eastern Basin NDCI: ${easternStats.ndci ? easternStats.ndci.toFixed(3) : 'N/A'} (Pixels: ${easternStats.pixels})`);

  if (westernStats.pixels === 0 || easternStats.pixels === 0) {
    console.log('No valid pixels after masking for one or both basins.');
    console.log('C2');
    return;
  }

  if (westernStats.ndci === null || easternStats.ndci === null || isNaN(westernStats.ndci) || isNaN(easternStats.ndci)) {
    console.log('Calculation for NDCI failed for one or both basins.');
    console.log('C3');
    return;
  }

  if (westernStats.ndci > easternStats.ndci) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
